  let lc = 0;
  let allKpIds: string[] = [];
  type LessonRef = { id: string; mindMap: MindNode | null };

  const lessonRefs: LessonRef[] = [];
  async function createLesson(unitId: string, title: string, opts: {
    num?: number; obj?: string; terms?: string; summary?: string; content?: string[];
    mindMap?: MindNode;
  }): Promise<LessonRef> {
    const l = await db.lesson.create({ data: {
      unitId, title,
      lessonNumber: opts.num || lc + 1,
      sortOrder: opts.num || lc + 1,
      learningObjectives: opts.obj || "",
      keyTerms: opts.terms || "",
      summary: opts.summary || "",
      content: opts.content ? doc(...opts.content) : undefined,
    }});
    if (opts.mindMap) await db.knowledgePoint.create({ data: { lessonId: l.id, title, difficulty: 3, tags: [], sortOrder: 1, content: doc("本课思维导图涵盖了核心知识结构，详见各子知识点。"), mindMapJson: opts.mindMap }});
    lc++;
    return { id: l.id, mindMap: opts.mindMap || null };
  }

  async function addKp(lessonId: string, title: string, d: number, tags: string[], content: string[], exam?: string, concepts?: { term: string; definition: string }[], misconceptions?: { statement: string; correction: string }[], mindMap?: MindNode) {
    const kp = await db.knowledgePoint.create({ data: {
      lessonId, title, difficulty: d, tags, sortOrder: 1,
      content: doc(...content),
      examRequirements: exam,
      keyConcepts: concepts,
      commonMisconceptions: misconceptions,
      mindMapJson: mindMap,
    }});
    allKpIds.push(kp.id);
    return kp;
  }

