      "新石器时代（距今1万年前开始）：生产方式为磨制石器，原始农业、原始畜牧业产生，人类进入定居农耕时代。早期遗存：仰韶文化（黄河中游，彩陶、种植粟）、河姆渡文化（长江下游，黑陶、人工栽培水稻）。晚期遗存：龙山文化、良渚文化、红山文化；核心变化：私有制产生、社会阶层分化、早期王权出现，具备早期国家形态。",
