     "四大国际会议：开罗会议（中英美要求日本归还侵占的中国领土）、德黑兰会议（美英苏决定开辟欧洲第二战场）、雅尔塔会议（确定战后格局和联合国）、波茨坦会议（发表《波茨坦公告》敦促日本投降）。",
