     "新经济政策（1921年开始）：以粮食税代替余粮收集制允许部分私营经济和自由贸易利用市场商品货币关系发展经济。适合俄国国情巩固了工农联盟。",
     "斯大林模式（20世纪20年代末形成）：高度集中的计划经济体制优先发展重工业农业全盘集体化。该模式短期内快速实现工业化为二战胜利奠定物质基础但长期忽视民生农业轻工业滞后体制日益僵化。",
